effect.shader:
void main(){
    vec2 uv = acScreenNorm - 0.5;
    uv.x *= acScreenSize.x/acScreenSize.y;
    float ang = atan(uv.y, uv.x) + radians(rotation);
    float rad = length(uv)/zoom;
    float seg = 6.28318/sides;
    ang = mod(ang, seg);
    ang = abs(ang - seg*0.5);
    vec2 nuv = vec2(cos(ang), sin(ang))*rad;
    nuv.x /= acScreenSize.x/acScreenSize.y;
    nuv += 0.5;
    nuv = abs(fract(nuv*0.5)*2.0 - 1.0);
    gl_FragColor = texture2DCv(inputImg.texture, nuv);
}
